function maximizeXor(nums, queries) {
  const sorted = [...nums].sort((a, b) => a - b);
  const order = queries.map((_, i) => i).sort((a, b) => queries[a][1] - queries[b][1]);
  const trie = [[0, 0]];
  const answer = new Array(queries.length).fill(-1);
  let next = 0;

  for (const q of order) {
    const [x, m] = queries[q];
    while (next < sorted.length && sorted[next] <= m) {
      let node = 0;
      for (let bit = 29; bit >= 0; bit--) {
        const b = (sorted[next] >> bit) & 1;
        if (trie[node][b] === 0) {
          trie[node][b] = trie.length;
          trie.push([0, 0]);
        }
        node = trie[node][b];
      }
      next++;
    }
    if (next === 0) {
      continue;
    }
    let node = 0;
    let best = 0;
    for (let bit = 29; bit >= 0; bit--) {
      const want = ((x >> bit) & 1) ^ 1;
      if (trie[node][want] !== 0) {
        best |= 1 << bit;
        node = trie[node][want];
      } else {
        node = trie[node][want ^ 1];
      }
    }
    answer[q] = best;
  }
  return answer;
}

