function maximizeXor(nums, queries) {
  return queries.map(([x, m]) => {
    let best = -1;
    for (const value of nums) {
      if (value <= m) best = Math.max(best, Number(BigInt(value) ^ BigInt(x)));
    }
    return best;
  });
}

