function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = [1000, 1 << 20, 1000000000][pick(0, 2)];
    const nums = Array.from({ length: pick(1500, 2000) }, () => pick(0, top));
    const queries = Array.from({ length: pick(1500, 2000) }, () => [pick(0, 1000000000), rand() < 0.1 ? pick(0, 50) : pick(0, top)]);
    return [nums, queries];
  }
  const top = [3, 15, 63][pick(0, 2)];
  const nums = Array.from({ length: pick(1, 8) }, () => pick(0, top));
  const queries = Array.from({ length: pick(1, 6) }, () => [pick(0, 2 * top + 1), pick(0, top + 2)]);
  return [nums, queries];
}
